/**
 * MB-004: vendored animation spec/LOCK tests.
 *
 * The plugin must verify its committed animation artifacts without the private
 * famling checkout. `scripts/spec/anim-spec.json` is the vendored semantic
 * spec + SHA-256 lock generated by `scripts/embed-anims.mjs`; these tests pin
 * its shape, its self-digest, the client.js/chunk/frame locks, and the
 * missing/tampered failure modes (a missing spec must fail, never skip).
 */
import assert from 'node:assert/strict'
import { existsSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { test } from 'node:test'

import { CHUNK_NAMES, PLUGIN_ROOT } from '../scripts/embed-anims.mjs'
import {
  SPEC_CHARACTERS,
  SPEC_RELATIVE_PATH,
  SPEC_VERSION,
  animationSpecSha256,
  readAnimationSpec,
  renderAnimationSpec,
  sha256Hex,
  stableStringify,
  validateEmbeddedAgainstSpec,
} from '../scripts/anim-spec.mjs'

const ROOT = PLUGIN_ROOT
const SPEC_PATH = join(ROOT, SPEC_RELATIVE_PATH)

test('vendored animation spec exists, parses and passes its own self-digest', () => {
  assert.ok(existsSync(SPEC_PATH), 'scripts/spec/anim-spec.json is committed')
  const { spec, text } = readAnimationSpec(ROOT)
  assert.equal(spec.schema, 'dsh-famling/anim-spec', 'schema')
  assert.equal(spec.specVersion, SPEC_VERSION, 'specVersion')
  assert.match(spec.specSha256, /^[0-9a-f]{64}$/, 'specSha256 is a SHA-256 hex digest')
  assert.equal(animationSpecSha256(spec), spec.specSha256, 'canonical body hashes to specSha256')
  assert.equal(text, renderAnimationSpec(spec), 'committed file equals the deterministic render')
})

test('vendored spec locks all three characters, all frames and the source frame manifest', () => {
  const { spec } = readAnimationSpec(ROOT)
  assert.deepEqual(Object.keys(spec.characters).sort(), [...SPEC_CHARACTERS].sort(), 'exactly human/cat/dog')
  let totalFrames = 0
  for (const kind of SPEC_CHARACTERS) {
    const character = spec.characters[kind]
    assert.equal(character.chunkFile, CHUNK_NAMES[kind], kind + ': chunk file name matches embed-anims')
    assert.match(character.chunkSha256, /^[0-9a-f]{64}$/, kind + ': chunk SHA-256')
    const clips = character.clips
    const spriteKeys = Object.values(clips).flatMap((clip) => clip.frames)
    assert.equal(spriteKeys.length, character.frames, kind + ': frame count matches clip data')
    assert.equal(character.embeddedFrameSha256.length, character.frames, kind + ': one embedded frame lock per frame')
    for (const hash of character.embeddedFrameSha256) assert.match(hash, /^[0-9a-f]{64}$/, kind + ': embedded frame hash format')
    assert.ok(Object.keys(clips).length === 12, kind + ': 12 shared clip ids')
    for (const [clipId, clip] of Object.entries(clips)) {
      clip.frames.forEach((spriteKey, index) => {
        assert.equal(spriteKey, kind + '/' + clipId + '/' + index, kind + ': sprite key layout')
      })
    }
    const sourceFrames = spec.sourceFrames[kind]
    const expectedSourceFiles = []
    for (const [clipId, clip] of Object.entries(clips)) {
      for (let index = 0; index < clip.frames.length; index += 1) {
        expectedSourceFiles.push(clipId + '/' + clipId + '_' + String(index).padStart(2, '0') + '.png')
      }
    }
    assert.deepEqual(Object.keys(sourceFrames).sort(), expectedSourceFiles.sort(), kind + ': source frame manifest is complete')
    for (const hash of Object.values(sourceFrames)) assert.match(hash, /^[0-9a-f]{64}$/, kind + ': source frame SHA-256')
    assert.equal(character.regions.canvas[0], 96, kind + ': 96px canvas')
    assert.equal(character.regions.canvas[1], 96, kind + ': 96px canvas')
    totalFrames += character.frames
  }
  assert.equal(totalFrames, 208, 'dog/human 68 + cat 72 = 208 frames')
})

test('committed client.js and lazy chunks match the vendored spec', () => {
  const { spec } = readAnimationSpec(ROOT)
  const result = validateEmbeddedAgainstSpec({ pluginRoot: ROOT, spec })
  assert.equal(result.ok, true, result.errors.join('; '))
  assert.equal(result.stats.characters, 3, 'three characters validated')
  assert.equal(result.stats.frames, 208, 'all 208 frames validated')
  const clientSource = readFileSync(join(ROOT, 'client.js'), 'utf8')
  assert.ok(clientSource.includes('// source-sha256: ' + spec.sourceSha256), 'client.js carries the spec source digest')
  for (const kind of SPEC_CHARACTERS) {
    const chunkSha = sha256Hex(readFileSync(join(ROOT, CHUNK_NAMES[kind]), 'utf8'))
    assert.equal(chunkSha, spec.characters[kind].chunkSha256, kind + ': chunk file SHA matches the spec')
  }
})

test('tampered spec or chunk is rejected (negative)', () => {
  const { spec } = readAnimationSpec(ROOT)
  const changed = JSON.parse(JSON.stringify(spec))
  changed.characters.dog.frames += 1
  assert.notEqual(animationSpecSha256(changed), spec.specSha256, 'any spec edit changes the self-digest')
  const frameResult = validateEmbeddedAgainstSpec({ pluginRoot: ROOT, spec: changed })
  assert.equal(frameResult.ok, false, 'edited frame count is rejected')
  assert.ok(frameResult.errors.some((problem) => problem.includes('frame count')), 'frame-count error reported: ' + frameResult.errors.join('; '))
  const sourceChanged = JSON.parse(JSON.stringify(spec))
  sourceChanged.sourceSha256 = '0'.repeat(64)
  const sourceResult = validateEmbeddedAgainstSpec({ pluginRoot: ROOT, spec: sourceChanged })
  assert.equal(sourceResult.ok, false, 'edited source digest is rejected')
  assert.ok(sourceResult.errors.some((problem) => problem.includes('source-sha256')), 'source digest error reported')
  // Tamper one embedded frame in an isolated copy of client.js + chunks.
  const temp = mkdtempSync(join(tmpdir(), 'dsh-famling-spec-tamper-'))
  try {
    const clientCopy = readFileSync(join(ROOT, 'client.js'), 'utf8')
    writeFileSync(join(temp, 'client.js'), clientCopy)
    for (const kind of SPEC_CHARACTERS) {
      const chunkSource = readFileSync(join(ROOT, CHUNK_NAMES[kind]), 'utf8')
      writeFileSync(join(temp, CHUNK_NAMES[kind]), chunkSource)
    }
    const dogChunk = readFileSync(join(temp, CHUNK_NAMES.dog), 'utf8')
    const marker = '"dog/idle/0": "'
    const index = dogChunk.indexOf(marker)
    assert.ok(index > 0, 'dog idle frame exists in the chunk')
    const offset = index + marker.length
    const replacement = dogChunk.slice(offset, offset + 1) === 'A' ? 'B' : 'A'
    writeFileSync(join(temp, CHUNK_NAMES.dog), dogChunk.slice(0, offset) + replacement + dogChunk.slice(offset + 1))
    const tampered = validateEmbeddedAgainstSpec({ pluginRoot: temp, spec })
    assert.equal(tampered.ok, false, 'edited chunk/frame is rejected')
    assert.ok(tampered.errors.some((problem) => problem.includes('sha256')), 'chunk/frame SHA mismatch reported')
  } finally {
    rmSync(temp, { recursive: true, force: true })
  }
})

test('a missing spec fails instead of skipping', () => {
  const temp = mkdtempSync(join(tmpdir(), 'dsh-famling-spec-missing-'))
  try {
    assert.throws(() => readAnimationSpec(temp), /vendored animation spec is missing/, 'missing spec throws a hard error')
  } finally {
    rmSync(temp, { recursive: true, force: true })
  }
})

test('stableStringify is deterministic and key-order independent', () => {
  assert.equal(stableStringify({ b: 1, a: [2, { d: 3, c: 4 }] }), stableStringify({ a: [2, { c: 4, d: 3 }], b: 1 }), 'key order does not change the digest input')
  assert.equal(sha256Hex('abc'), 'ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad', 'SHA-256 sanity check')
})
